use hy_check::check_file;
use hy_syntax::parse_file;
fn codes(src: &str) -> Vec<String> { check_file(&parse_file("test.hy", src).unwrap()).diagnostics.into_iter().map(|d| d.code.into()).collect() }
#[test] fn t24_rejects_addr_of_field_on_slot_loan() { let src = "package p\n\nstruct node_t {\n    count int\n}\n\nfn bad() {\n    m := map[string]node_t{\"a\": node_t{count: 1}}\n    n := &m[\"a\"]\n    p := &n.count\n    _ = p\n}"; assert_eq!(codes(src), vec!["HYB-E3104"]); }
#[test] fn t24_rejects_addr_of_array_or_slice_index_on_slot_loan() { let src = "package p\n\nstruct node_t {\n    items []int\n}\n\nfn bad() {\n    m := map[string]node_t{\"a\": node_t{items: []int{1, 2}}}\n    n := &m[\"a\"]\n    p := &n.items[0]\n    _ = p\n}"; assert_eq!(codes(src), vec!["HYB-E3104"]); }
#[test] fn t24_accepts_nested_map_slot_loan_on_slot_loan_map_field() { let src = "package p\n\nstruct group_t {\n    sub map[string]int\n}\n\nfn ok() {\n    groups := map[string]group_t{\"g\": group_t{sub: map[string]int{\"x\": 1}}}\n    n := &groups[\"g\"]\n    slot := &n.sub[\"x\"]\n    _ = slot\n}"; assert!(codes(src).is_empty(), "expected 0 diags, got {:?}", codes(src)); }
#[test] fn t24_rejects_addr_of_slot_loan_after_conditional_reassign() { let src = "package p\n\nstruct node_t {\n    count int\n}\n\nfn bad(cond bool) {\n    m := map[string]node_t{\"a\": node_t{count: 1}}\n    var n node_t = node_t{count: 0}\n    n = &m[\"a\"]\n    if cond {\n        n = node_t{count: 2}\n    }\n    p := &n\n    _ = p\n}"; assert_eq!(codes(src), vec!["HYB-E3104"]); }
#[test] fn t24_accepts_addr_of_after_unconditional_same_scope_reassign() { let src = "package p\n\nstruct node_t {\n    count int\n}\n\nfn ok() {\n    m := map[string]node_t{\"a\": node_t{count: 1}}\n    var n node_t = node_t{count: 0}\n    n = &m[\"a\"]\n    n = node_t{count: 2}\n    p := &n\n    _ = p\n}"; assert!(codes(src).is_empty(), "expected 0 diags, got {:?}", codes(src)); }
#[test] fn o2_rejects_return_of_borrow_after_inner_block_shadow() { let src = "package p\n\nstruct box_t {\n    v int\n}\n\nfn bad() (*box_t) {\n    x := box_t{v: 1}\n    p := &x\n    if true {\n        p := 1\n        _ = p\n    }\n    return p\n}"; assert_eq!(codes(src), vec!["HYB-E3104"]); }
#[test] fn o2_rejects_return_of_borrow_after_conditional_reassign() { let src = "package p\n\nstruct box_t {\n    v int\n}\n\nfn bad(cond bool, fallback *box_t) (*box_t) {\n    x := box_t{v: 1}\n    p := &x\n    if cond {\n        p = fallback\n    }\n    return p\n}"; assert_eq!(codes(src), vec!["HYB-E3104"]); }
#[test] fn o2_rejects_bare_return_of_named_result_after_conditional_borrow_assign() { let src = "package p\n\nstruct box_t {\n    v int\n}\n\ntype box_ptr = *box_t\n\nfn bad(cond bool, fallback box_ptr) (out box_ptr) {\n    x := box_t{v: 1}\n    if cond {\n        out = &x\n    } else {\n        out = fallback\n    }\n    return\n}"; assert_eq!(codes(src), vec!["HYB-E3104"]); }
#[test] fn t24_rejects_same_stmt_parallel_assign_slot_loan_addr_of() { let src = "package p\n\nstruct node_t {\n    count int\n}\n\nfn bad(fallback *node_t) {\n    m := map[string]node_t{\"a\": node_t{count: 1}}\n    var n node_t = node_t{count: 0}\n    var p *node_t = fallback\n    n, p = &m[\"a\"], &n\n    _ = p\n}"; assert_eq!(codes(src), vec!["HYB-E3104"]); }
#[test] fn t24_rejects_same_stmt_parallel_local_redecl_slot_loan_addr_of() { let src = "package p\n\nstruct node_t {\n    count int\n}\n\nfn bad() {\n    m := map[string]node_t{\"a\": node_t{count: 1}}\n    n := node_t{count: 0}\n    n, p := &m[\"a\"], &n\n    _ = p\n}"; assert_eq!(codes(src), vec!["HYB-E3104"]); }
#[test] fn t24_rejects_addr_of_captured_or_local_slot_loan_inside_closure() { let src = "package p\n\nstruct node_t {\n    count int\n}\n\nfn bad() {\n    m := map[string]node_t{\"a\": node_t{count: 1}}\n    n := &m[\"a\"]\n    f := fn() {\n        p1 := &n\n        k := &m[\"a\"]\n        p2 := &k\n        _ = p1\n        _ = p2\n    }\n    _ = f\n}"; assert_eq!(codes(src), vec!["HYB-E3104", "HYB-E3104"]); }
#[test] fn o2_rejects_closure_return_of_assigned_local_borrow() { let src = "package p\n\nstruct box_t {\n    v int\n}\n\nfn bad(fallback *box_t) {\n    f := fn() (*box_t) {\n        var p *box_t = fallback\n        x := box_t{v: 1}\n        p = &x\n        return p\n    }\n    _ = f\n}"; assert_eq!(codes(src), vec!["HYB-E3104"]); }
